mapper.select:
SELECT
    T.IMPORT_ID, T.IMPORT_TYPE, T.FILE_NAME, T.FILE_URL, T.IMPORT_TOTAL, T.SUCCESS_TOTAL, T.FAILURE_TOTAL,
    T.PROCESS_STATE, T.PROCESS_INFO, T.CREATE_BY, T.CREATE_TIME, T.UPDATE_BY, T.UPDATE_TIME, T.DEPT_ID
FROM sys_import_record T

     AND T.IMPORT_ID = #{importId}
     AND T.IMPORT_TYPE = #{importType}
     AND T.FILE_NAME like concat('%',#{fileName},'%')
     AND T.PROCESS_STATE = #{processState}
     AND T.CREATE_BY = #{createBy}
    ${dataScope}

ORDER BY T.CREATE_TIME DESC
